import LogoIcon from './icons/LogoIcon'
import BagIcon from './icons/BagIcon'

function SvgIcon({ viewBox, children, className = 'h-5 w-5' }) {
  return (
    <svg viewBox={viewBox} fill="none" className={className} aria-hidden="true">
      {children}
    </svg>
  )
}

function MenuIcon() {
  return (
    <SvgIcon viewBox="26 94.709 20 20">
      <path
        d="M28.125 99.8342H36H43.875M28.125 104.709H43.875M28.125 109.584H43.875"
        stroke="currentColor"
        strokeWidth="2"
        strokeMiterlimit="10"
        strokeLinecap="round"
      />
    </SvgIcon>
  )
}

