function Sidebar() {
  const items = [
    { label: 'Menu', icon: <MenuIcon /> },
    { label: 'Store', icon: <StoreIcon />, active: true },
    { label: 'Bag', icon: <BagIcon /> },
  ]

  return (
    <aside className="flex w-[72px] shrink-0 flex-col items-center justify-between rounded-lg bg-white p-4">
      <div className="flex flex-col items-center gap-8">
        <LogoIcon />
        {items.map((item) => (
          <button
            key={item.label}
            aria-label={item.label}
            className={`flex h-10 w-10 items-center justify-center rounded-[10px] ${
              item.active ? 'bg-[#1A1F16] text-white' : 'text-[#1A1F16]'
            }`}
          >
            {item.icon}
          </button>
        ))}
      </div>

      <button
        aria-label="Log out"
        className="flex h-10 w-10 items-center justify-center rounded-[10px] bg-[#E5252C] text-white"
      >
        <LogoutIcon />
      </button>
    </aside>
  )
}

export default Sidebar